import urllib.request, xml.etree.ElementTree as ET
u='https://export.arxiv.org/api/query?id_list=2305.05065,2505.09205,2108.08134'
r=ET.fromstring(urllib.request.urlopen(u).read()); ns={'a':'http://www.w3.org/2005/Atom'}
for e in r.findall('a:entry',ns): print(e.findtext('a:title',namespaces=ns),e.findtext('a:summary',namespaces=ns)[:1200])
PY

